import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-BVtXrkU4.js";import{t as r}from"./app-DixIL8sc.js";var i=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S04/S04E21.html","title":"S04E21 The One with the Invitation","lang":"zh-CN","frontmatter":{"title":"S04E21 The One with the Invitation","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":94},"git":{"createdTime":1780654155000,"updatedTime":1780654155000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":33.89,"words":10168},"filePathRelative":"语言/英语/Friends老友记/S04/S04E21.md"}`),a={name:`S04E21.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-one-with-the-invitation" tabindex="-1"><a class="header-anchor" href="#the-one-with-the-invitation"><span>The One with the Invitation</span></a></h1><blockquote><p><em>带邀请函的那个</em></p></blockquote><p>The One With The Invitation</p><blockquote><p>带邀请函的那个</p></blockquote><p><strong>Written by: Seth Kirkland</strong></p><blockquote><p>作者：塞思·柯克兰</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><p><strong>With Help from:</strong> Darcy Partridge</p><blockquote><p>在达西·帕特里奇的帮助下</p></blockquote><p><strong>Episodes Orginally Transcribed by:</strong> guineapig, Ruth Curran, Mindy Mattingly Phillips, Josh Hodge, Dan Silverstein, and Eric Aasen.</p><blockquote><p>几内亚比格、露丝·科伦、明迪·马丁利·菲利普斯、乔什·霍奇、丹·西尔弗斯坦和埃里克·艾森。</p></blockquote><hr><p>🎬 <em>Central Perk, Joey and Chandler are sitting and talking.</em></p><blockquote><p>🎬 <em>中央公园，乔伊和钱德勒坐着聊天。</em></p></blockquote><p><strong>Chandler Bing:</strong> Y’know what? It seems like all of the sudden; so much has happened.</p><blockquote><p>你知道吗？这似乎是突然发生的；发生了这么多事情。</p></blockquote><p><strong>Joey Tribbiani:</strong> I know. Ross is getting married.</p><blockquote><p>我知道。罗斯要结婚了。</p></blockquote><p><strong>Chandler Bing:</strong> Phoebe is, making people.</p><blockquote><p>菲比是，制造人。</p></blockquote><p><strong>Joey Tribbiani:</strong> Everybody’s doing stuff!</p><blockquote><p>每个人都在做事！</p></blockquote><p><strong>Chandler Bing:</strong> And we just sit here. I mean if I die the only way people would even know I was here, would be by the ass print on this chair! Look, we have to do something. Okay? Something huge!</p><blockquote><p>我们就坐在这里。我的意思是，如果我死了，人们知道我在这里的唯一方法就是看这把椅子上的屁股印！听着，我们得做点什么。可以巨大的东西！</p></blockquote><p><strong>Joey Tribbiani:</strong> (snaps his fingers) We could climb Mt. Everest!</p><blockquote><p>（啪的一声手指）我们可以爬珠穆朗玛峰！</p></blockquote><p><strong>Chandler Bing:</strong> No-no, not something stupid, something huge.</p><blockquote><p>不，不，不是愚蠢的东西，而是巨大的东西。</p></blockquote><p><strong>Joey Tribbiani:</strong> No-no-no-no-no, I saw an ad for this video, people climb that thing everyday! We could totally do that!</p><blockquote><p>不不不，我看到这段视频的广告，人们每天都爬那个东西！我们完全可以做到！</p></blockquote><p><strong>Chandler Bing:</strong> Why not?! I mean it’s just, it’s just climbing! It’s just, it’s just steep!</p><blockquote><p>为什么不呢？！我是说，只是，只是爬山！只是，只是太陡了！</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah!</p><blockquote><p>是啊！</p></blockquote><p><strong>Chandler Bing:</strong> We’re going to Everest! Okay, it would be nice to leave an ass print on Everest!</p><blockquote><p>我们要去珠穆朗玛峰！好吧，在珠穆朗玛峰上留下屁股印就好了！</p></blockquote><p><strong>Phoebe Buffay:</strong> (entering) Hey!</p><blockquote><p>（进来）嘿！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Phoebe Buffay:</strong> What-what’s up?</p><blockquote><p>怎么了？</p></blockquote><p><strong>Joey Tribbiani:</strong> We’re gonna climb Mt. Everest!</p><blockquote><p>我们要去攀登珠穆朗玛峰！</p></blockquote><p><strong>Chandler Bing:</strong> Yeah baby!</p><blockquote><p>是的，宝贝！</p></blockquote><p><strong>Phoebe Buffay:</strong> Really?! I looked into that. Yeah, but, I mean it costs like $60,000 and y’know you can die. And, you would die!</p><blockquote><p>真的吗？！我调查过了。是的，但是，我的意思是它要花60000美元，你知道你会死的。你会死的！</p></blockquote><p><strong>Chandler Bing:</strong> (dejected) Yeah, well…</p><blockquote><p>（沮丧地）是的，嗯…</p></blockquote><p><strong>Joey Tribbiani:</strong> We could get that Everest video though.</p><blockquote><p>不过我们可以拿到珠穆朗玛峰的录像带。</p></blockquote><p><strong>Chandler Bing:</strong> Yeah, we could do that without y’know risking our lives at all!</p><blockquote><p>是的，我们可以做到，而不用冒生命危险！</p></blockquote><p><strong>Joey Tribbiani:</strong> And while we’re down at the video store, you know what else we could rent? Die Hard! (Chandler’s excited.) Oh, y’know what? I just remembered, that Everest thing is only available through mail order.</p><blockquote><p>当我们在音像店的时候，你知道我们还能租什么吗？死定了！（钱德勒很兴奋）哦，你知道吗？我刚想起来，珠穆朗玛峰的东西只有邮购才能买到。</p></blockquote><p><strong>Chandler Bing:</strong> (dejected) Oh, well…</p><blockquote><p>（沮丧地）哦，好吧…</p></blockquote><p><strong>Phoebe Buffay:</strong> So you guys’ll stay here and hang out with me?</p><blockquote><p>所以你们会留在这里和我一起玩？</p></blockquote><p><strong>Chandler Bing:</strong> Yeeeeahhhh.</p><blockquote><p>是的。</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah. Yeah.</p><blockquote><p>是的。是 啊</p></blockquote><p><strong>Chandler Bing:</strong> But I’ll tell you something. One of these days we’re get off of our buts and rent Die Hard again!</p><blockquote><p>但我要告诉你一件事。总有一天，我们会从我们的房子里出来，租房又会变得很难！</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah we are!</p><blockquote><p>是的，我们是！</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Ross’s apartment, he and Emily are addressing their invitations.</em></p><blockquote><p>🎬 <em>罗斯的公寓，他和艾米丽正在处理他们的邀请。</em></p></blockquote><p><strong>Emily:</strong> So what did he decide? Does your Uncle Nathan get an invite or not?</p><blockquote><p>那他是怎么决定的？你叔叔内森收到邀请了吗？</p></blockquote><p><strong>Ross Geller:</strong> Ohh, God, nobody likes him, and he’s so cheap, he’d never fly to London in a million years. Yeah, invite him? Hey, did I do these neat enough? (Hands her some envelopes.)</p><blockquote><p>哦，天哪，没人喜欢他，而且他很便宜，一百万年内他都不会飞到伦敦了。是的，邀请他？嘿，我做的够整洁吗？（递给她一些信封。）</p></blockquote><p><strong>Emily:</strong> Yeah, they’re fine.</p><blockquote><p>是的，他们很好。</p></blockquote><p><strong>Ross Geller:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Emily:</strong> If anyone asks, we’ll just say Ben addressed them. (Looking through the envelopes.) Oh! So you invited Rachel then?</p><blockquote><p>如果有人问起，我们就说本是给他们写信的。（看着信封）哦！那么你邀请了瑞秋？</p></blockquote><p><strong>Ross Geller:</strong> Sure. Why not?</p><blockquote><p>当然。为什么不呢？</p></blockquote><p><strong>Emily:</strong> Really?</p><blockquote><p>真的吗？</p></blockquote><p><strong>Ross Geller:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Emily:</strong> I don’t think I’d be comfortable with any of my old lovers there.</p><blockquote><p>我想我和我的老情人在一起会很不舒服。</p></blockquote><p><strong>Ross Geller:</strong> Wait-wait-wait, do you, do you think, maybe we shouldn’t invite her?</p><blockquote><p>等等，你觉得我们不应该邀请她吗？</p></blockquote><p><strong>Emily:</strong> Oh, no-no, y’know I absolutely adore Rachel it’s just that, well it might be a awkward for you. But it’s absolutely your decision. (Gets up.) More tea?</p><blockquote><p>哦，不，不，你知道我非常喜欢瑞秋，只是，对你来说可能会很尴尬。但这绝对是你的决定。（起床）还要茶吗？</p></blockquote><p><strong>Ross Geller:</strong> Yeah sure.</p><blockquote><p>是的，当然。</p></blockquote><p><strong>Emily:</strong> Earl Grey?</p><blockquote><p>格雷伯爵？</p></blockquote><p><strong>Ross Geller:</strong> Huh? Yeah, fine, invite whoever you want.</p><blockquote><p>嗯？好吧，你想邀请谁就邀请谁。</p></blockquote><p>[And with that we start off on a series of clips from the entire history of Ross and Rachel, from Ross’s point of view. The first clip is from The Pilot.]</p><blockquote><p>[从罗斯的角度出发，我们从罗斯和瑞秋整个历史的一系列剪辑开始。第一个剪辑来自飞行员。]</p></blockquote><hr><p>🎬 <em>Central Perk, Ross is complaining about Carol.</em></p><blockquote><p>🎬 <em>中央公园，罗斯在抱怨卡萝。</em></p></blockquote><p><strong>Ross Geller:</strong> I don&#39;t want to be single, okay? I just... I just- I just wanna be married again!</p><blockquote><p>我不想单身，好吗？我只是。。。我只是-我只是想再婚！</p></blockquote><p><em>(A woman enters wearing a wet wedding dress and frantically starts to look around.)</em></p><blockquote><p><em>（一位穿着湿婚纱的女士走进来，疯狂地四处张望。）</em></p></blockquote><p><strong>Chandler Bing:</strong> And I just want a million dollars! (He extends his hand hopefully.)</p><blockquote><p>我只想要一百万美元！（他满怀希望地伸出手。）</p></blockquote><p><strong>Monica Geller:</strong> Rachel?!</p><blockquote><p>瑞秋？！</p></blockquote><p><strong>Rachel Green:</strong> Oh God Monica hi! I just went to your building and you weren&#39;t there and then this guy with a big hammer said you might be here and you are, you are!</p><blockquote><p>哦，天哪，莫妮卡，嗨！我刚去了你的大楼，你不在那里，然后一个拿着大锤子的家伙说你可能在这里，你在，你在！</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><strong>Monica Geller:</strong> Okay, everybody, this is Rachel, another Lincoln High survivor. (To Rachel) This is everybody, this is Chandler, and Phoebe, and Joey, and- you remember my brother Ross?</p><blockquote><p>好的，各位，这是瑞秋，另一位林肯高中的幸存者。（对瑞秋）这是所有人，这是钱德勒、菲比和乔伊，你还记得我哥哥罗斯吗？</p></blockquote><p><strong>Rachel Green:</strong> Hi, sure!</p><blockquote><p>嗨，当然！</p></blockquote><p><strong>Ross Geller:</strong> Hi.</p><blockquote><p>嗨。</p></blockquote><p><em>(They go to hug but Ross&#39; umbrella opens. He sits, defeated again.)</em></p><blockquote><p><em>（他们去拥抱，但罗斯的伞打开了。他坐着，又被打败了。）</em></p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Ross and Rachel are finishing up some cookies.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，罗斯和瑞秋正在做饼干。</em></p></blockquote><p><strong>Ross Geller:</strong> You know you probably didn&#39;t know this, but back in high school, I had a, um, major crush on you.</p><blockquote><p>你知道你可能不知道，但在高中的时候，我对你有一种，嗯，强烈的迷恋。</p></blockquote><p><strong>Rachel Green:</strong> I knew.</p><blockquote><p>我知道。</p></blockquote><p><strong>Ross Geller:</strong> You did! Oh.... I always figured you just thought I was Monica&#39;s geeky older brother.</p><blockquote><p>是的！哦我一直以为你以为我是莫妮卡的怪哥哥。</p></blockquote><p><strong>Rachel Green:</strong> I did.</p><blockquote><p>是的。</p></blockquote><p><strong>Ross Geller:</strong> Oh. Listen, do you think- and try not to let my intense vulnerability become any kind of a factor here—but do you think it would be okay if I asked you out? Sometime? Maybe?</p><blockquote><p>哦。听着，你认为——尽量不要让我强烈的脆弱性成为这里的一个因素，但你认为如果我约你出去会好吗？在某时大概</p></blockquote><p><strong>Rachel Green:</strong> Yeah, maybe...</p><blockquote><p>是的，也许。。。</p></blockquote><p><strong>Ross Geller:</strong> Okay... okay, maybe I will...</p><blockquote><p>好的。。。好吧，也许我会。。。</p></blockquote><p>[The next clip is from The One With The Blackout.]</p><blockquote><p>[下一个剪辑来自发生停电的剪辑。]</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Ross and Rachel are talking about passion.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，罗斯和瑞秋正在谈论激情。</em></p></blockquote><p><strong>Ross Geller:</strong> See, I see.... big passion in your future.</p><blockquote><p>看，我明白了。。。。对你的未来充满激情。</p></blockquote><p><strong>Rachel Green:</strong> Really?</p><blockquote><p>真的吗？</p></blockquote><p><strong>Ross Geller:</strong> I do.</p><blockquote><p>是的。</p></blockquote><p><strong>Rachel Green:</strong> Oh Ross, you&#39;re so great. [she playfully rubs his head and gets up]</p><blockquote><p>哦，罗斯，你太棒了。[她顽皮地揉着他的头，站了起来]</p></blockquote><p>[Ross gets up, pleased with himself and starts to walk past Joey.]</p><blockquote><p>[罗斯站起来，自鸣得意，开始从乔伊身边走过。]</p></blockquote><p><strong>Joey Tribbiani:</strong> It&#39;s never gonna happen.</p><blockquote><p>这永远不会发生。</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s balcony, Ross is about to be attacked by Paulo&#39;s cat.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的阳台，罗斯即将被保罗的猫袭击。</em></p></blockquote><p><strong>Ross Geller:</strong> Hey, I have a question. Well, actually, it&#39;s not so much a question as.. more of a general wondering... ment.</p><blockquote><p>嘿，我有个问题。事实上，这与其说是个问题不如说是。。更多的是一个普遍的疑问。。。是的。</p></blockquote><p><strong>Rachel Green:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Ross Geller:</strong> Okay. Umm, for a while now, I&#39;ve been wanting to, um....</p><blockquote><p>好的。嗯，有一段时间，我一直想，嗯。。。。</p></blockquote><p><strong>Rachel Green:</strong> Ohhh!!!! [looking at something behind Ross]</p><blockquote><p>哦！！！！[看着罗斯身后的东西]</p></blockquote><p><strong>Ross Geller:</strong> Yes, yes, that&#39;s right...</p><blockquote><p>是的，是的，没错。。。</p></blockquote><p><strong>Rachel Green:</strong> Oh, look at the little cat! [a small kitten is on the roof behind Ross] Look at it!</p><blockquote><p>哦，看那只小猫！[一只小猫在罗斯身后的屋顶上]看！</p></blockquote><p><strong>Ross Geller:</strong> What? [the cat jumps on his shoulders] Ow!</p><blockquote><p>什么？[猫跳到他的肩膀上]哇！</p></blockquote><p>[Cut to inside, Monica, Joey and Phoebe are singing while outside, Ross and Rachel are trying to get the cat off of Ross&#39; shoulder.]</p><blockquote><p>[切到里面，莫妮卡、乔伊和菲比在唱歌，而在外面，罗斯和瑞秋正试图把猫从罗斯的肩膀上弄下来。]</p></blockquote><p>Monica, Joey, and **Phoebe Buffay: **[singing] I&#39;m on top of the world, looking down on creation and the only explanation I can find...</p><blockquote><p>莫妮卡、乔伊和<strong>菲比·布菲：</strong>[唱歌]我站在世界之巅，俯视着创造和我能找到的唯一解释。。。</p></blockquote><p>[The next clip is from The One With The East German Laundry Detergent.]</p><blockquote><p>[下一个剪辑来自使用东德洗衣粉的剪辑。]</p></blockquote><hr><p>🎬 <em>The Laundromat, Rachel is fighting with that old, annoying woman for a cart.</em></p><blockquote><p>🎬 <em>洗衣店，瑞秋正和那个讨厌的老女人争夺一辆手推车。</em></p></blockquote><p><strong>Rachel Green:</strong> All right, listen, missy. If you want this cart, you&#39;re gonna have to take me with it!</p><blockquote><p>好吧，听着，小姐。如果你想要这辆车，你就得带上我！</p></blockquote><p><em>(She thinks it over, and then walks away.)</em></p><blockquote><p><em>（她仔细考虑了一下，然后走开了。）</em></p></blockquote><p><strong>Rachel Green:</strong> (to Ross) Yes! Did you see that?</p><blockquote><p>（对罗斯）是的！你看到了吗？</p></blockquote><p><strong>Ross Geller:</strong> You were incredible! Brand new woman, ladies and gentlemen.</p><blockquote><p>你太棒了！全新的女性，女士们，先生们。</p></blockquote><p><strong>Rachel Green:</strong> I could not have done this without you.</p><blockquote><p>没有你，我不可能做到这一点。</p></blockquote><p><em>(Rachel stands up and kisses Ross. He is stunned. A moment of silence follows.)</em></p><blockquote><p><em>（瑞秋站起来吻了吻罗斯。罗斯惊呆了。接着是沉默。）</em></p></blockquote><p><strong>Ross Geller:</strong> Ok, um, uh, more clothes in the dryer? (Ross turns and bangs his head on an open dryer door.) I&#39;m fine, I&#39;m fine.</p><blockquote><p>好的，嗯，嗯，干衣机里还有衣服吗？（罗斯转过身，把头撞在打开的烘干机门上。）我很好，我很好。</p></blockquote><p>[The next clip is from The One Where Ross Finds Out]</p><blockquote><p>[下一个剪辑来自罗斯发现的那一个]</p></blockquote><hr><p>🎬 <em>Central Perk, I&#39;m sure you&#39;ve guessed, it&#39;s the famous fight scene between Ross and Rachel.</em></p><blockquote><p>🎬 <em>中央公园，我相信你已经猜到了，这是罗斯和瑞秋之间著名的搏斗场景。</em></p></blockquote><p><strong>Ross Geller:</strong> You had no right to tell me you ever had feelings for me.</p><blockquote><p>你没有权利告诉我你对我有过感情。</p></blockquote><p><strong>Rachel Green:</strong> (hurt) What?</p><blockquote><p>（受伤）什么？</p></blockquote><p><strong>Ross Geller:</strong> I was doing great with Julie before I found out about you.</p><blockquote><p>在我发现你之前，我和朱莉相处得很好。</p></blockquote><p><strong>Rachel Green:</strong> Hey, I was doin&#39; great before I found out about you. You think it&#39;s easy for me to see you with Julie?</p><blockquote><p>嘿，在我发现你之前我做得很好。你觉得我很容易看到你和朱莉在一起？</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><strong>Ross Geller:</strong> The point is I... I don&#39;t need this right now, OK. It, it&#39;s too late, I&#39;m with somebody else, I&#39;m happy. This ship has sailed.</p><blockquote><p>重点是我。。。我现在不需要这个，好吗。太晚了，我和别人在一起，我很高兴。这艘船已经开航了。</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><strong>Rachel Green:</strong> Alright, fine, you go ahead and you do that, alright Ross.</p><blockquote><p>好吧，好吧，你去做吧，罗斯。</p></blockquote><p><strong>Ross Geller:</strong> Fine.</p><blockquote><p>好的。</p></blockquote><p><strong>Rachel Green:</strong> &#39;Cause I don&#39;t need your stupid ship.</p><blockquote><p>因为我不需要你那艘愚蠢的飞船。</p></blockquote><p><strong>Ross Geller:</strong> Good.</p><blockquote><p>很好。</p></blockquote><p><strong>Rachel Green:</strong> Good. (Ross leaves)</p><blockquote><p>很好。（罗斯离开）</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><em>(Rachel slams the door and locks it. She sits down, visibly upset. She puts her head in her hands and begins to cry. Ross comes back and is standing outside the window. When Rachel regroups and gets back up to finish closing, she sees him.)</em></p><blockquote><p><em>（瑞秋砰的一声关上门。她坐了下来，显然很不高兴。她双手捂着头哭了起来。罗斯回来站在窗外。当瑞秋重新站起来准备关门时，她看到了他。）</em></p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><em>(She opens the door and they kiss.)</em></p><blockquote><p><em>（她打开门，他们接吻。）</em></p></blockquote><p>[The next clip is the second famous fight in The One Where Ross and Rachel Take A Break.]</p><blockquote><p>[下一个剪辑是罗斯和瑞秋休息的第二场著名比赛。]</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Ross and Rachel are arguing.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，罗斯和瑞秋在争吵。</em></p></blockquote><p><strong>Rachel Green:</strong> Ross do you realise this is the first time in my life I’m doing something I actually care about. This is the first time in my life I’m doing something that I’m actually good at. I mean. if you don’t get that...</p><blockquote><p>罗斯，你知道这是我这辈子第一次做我真正关心的事情吗。这是我有生以来第一次做我真正擅长的事情。我是说。如果你不明白。。。</p></blockquote><p><strong>Ross Geller:</strong> No, hey, I get that, okay, I get that big time. And I’m happy for ya, but I’m tired of having a relationship with your answering machine! Okay, I don’t know what to do anymore.</p><blockquote><p>不，嘿，我明白了，好吧，我明白了。我为你感到高兴，但我厌倦了和你的电话答录机发生关系！好吧，我不知道该怎么办了。</p></blockquote><p><strong>Rachel Green:</strong> Well neither do I!</p><blockquote><p>我也是！</p></blockquote><p><strong>Ross Geller:</strong> Is this about Mark?</p><blockquote><p>这是关于马克的吗？</p></blockquote><p><strong>Rachel Green:</strong> (shocked) Oh my God.</p><blockquote><p>（震惊）哦，我的天啊。</p></blockquote><p><strong>Ross Geller:</strong> Okay, it’s not, it’s not.</p><blockquote><p>好吧，不是，不是。</p></blockquote><p><strong>Rachel Green:</strong> Oh my God. I cannot keep having this same fight over and over again, Ross, no, you’re, you’re, you’re making this too hard.</p><blockquote><p>我的天啊。我不能一次又一次地打同样的仗，罗斯，不，你，你，你让这太难了。</p></blockquote><p><strong>Ross Geller:</strong> Oh I’m, I’m making this too hard. Okay, what do you want me to do.</p><blockquote><p>哦，我，我太难了。好吧，你想让我做什么。</p></blockquote><p><strong>Rachel Green:</strong> I don’t know, I don’t know. Urrrgh! Look, maybe we should take a break.</p><blockquote><p>我不知道，我不知道。呃！听着，也许我们应该休息一下。</p></blockquote><p><strong>Ross Geller:</strong> Okay, okay, fine, you’re right. Let’s ah, let’s take a break, (goes to the door) let’s cool off, okay, let’s get some frozen yogart, or something.. (opens the door)</p><blockquote><p>好吧，好吧，好吧，你说得对。让我们休息一下，（走到门口）让我们冷静下来，好吧，我们来点冰冻酸奶，或者别的什么。（开门）</p></blockquote><p><strong>Rachel Green:</strong> No. (Ross is standing in the doorway.) A break from us.</p><blockquote><p>不。（罗斯站在门口。）和我们分手。</p></blockquote><p><em>(Ross looks at her, then leaves slamming the door behind him.)</em></p><blockquote><p><em>（罗斯看着她，然后砰地关上门离开。）</em></p></blockquote><p>[The next clip is from The One The Morning After]</p><blockquote><p>[下一个剪辑来自第二天早上的剪辑]</p></blockquote><hr><p>🎬 <em>Ross&#39;s apartment, Ross is hurrying Chloe out the door.</em></p><blockquote><p>🎬 <em>罗斯的公寓，罗斯正催着克洛伊出门。</em></p></blockquote><p><strong>Chloe:</strong> Do I know why we’re rushing?</p><blockquote><p>我知道我们为什么要赶吗？</p></blockquote><p><strong>Ross Geller:</strong> Yeah, y&#39;know the ah, the girlfriend I told you about last night? (He’s frantically throwing the cushions off of the couch looking for her other shoe) Well it turns out she ah, she wants to get back together with me. Oh, I found it!!</p><blockquote><p>是啊，你知道我昨晚跟你说的那个女朋友吗？（他疯狂地从沙发上扔下垫子，寻找她的另一只鞋）原来她啊，她想和我重归于好。哦，我找到了！！</p></blockquote><p><strong>Chloe:</strong> That’s so great for you guys!</p><blockquote><p>这对你们来说太棒了！</p></blockquote><p><strong>Ross Geller:</strong> Yeah!</p><blockquote><p>是啊！</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><strong>Chloe:</strong> Good luck, with your girlfriend.</p><blockquote><p>祝你好运，和你的女朋友在一起。</p></blockquote><p><strong>Ross Geller:</strong> Oh, thank you. (She goes to kiss him, but he holds her coat up between their faces to stop her.) Hey, hey. (opens the door, sees Rachel, and hides Chloe behind the door) Rachel!!!!</p><blockquote><p>哦，谢谢你。（她去吻他，但他把她的外套夹在两人的脸之间阻止她。）嘿，嘿。（打开门，看到瑞秋，把克洛伊藏在门后）瑞秋！！！！</p></blockquote><p><strong>Rachel Green:</strong> Hi. Ohhh, you got my message.</p><blockquote><p>嗨。哦，你收到我的留言了。</p></blockquote><p><strong>Ross Geller:</strong> Yeah, oh hey, you are right on time.</p><blockquote><p>是啊，哦，嘿，你准时到了。</p></blockquote><p><strong>Rachel Green:</strong> So what do you say? Can I be your girlfriend again?</p><blockquote><p>那你怎么说？我能再做你的女朋友吗？</p></blockquote><p><strong>Ross Geller:</strong> Yes, you can, very much.</p><blockquote><p>是的，你可以，非常喜欢。</p></blockquote><p><em>(Chloe gives Ross the thumbs up while still standing behind the door.)</em></p><blockquote><p><em>（克洛伊站在门后，竖起了罗斯的大拇指。）</em></p></blockquote><p><strong>Ross Geller:</strong> (seeing the thumbs up) Ahhhh!! (Hugs Rachel tighter.)</p><blockquote><p>（竖起大拇指）啊！！（紧紧拥抱瑞秋。）</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Rachel has just found out about Chloe and is screaming at Ross. The rest of the gang is trapped in Monica&#39;s bedroom.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，瑞秋刚发现克洛伊的事，冲着罗斯大喊大叫。其他人被困在莫妮卡的卧室里。</em></p></blockquote><p><strong>Rachel Green:</strong> (opening the door) Y&#39;know what, I want you to leave! Get outta here!</p><blockquote><p>（开门）你知道吗，我要你离开！离开这里！</p></blockquote><p><strong>Ross Geller:</strong> No!!</p><blockquote><p>不！！</p></blockquote><p><strong>Rachel Green:</strong> Just get out! Now!!</p><blockquote><p>滚出去！现在！！</p></blockquote><p><strong>Ross Geller:</strong> No!! No!! I wanna stay. I wanna talk about this.</p><blockquote><p>不！！不我想留下来。我想谈谈这个。</p></blockquote><p><strong>Rachel Green:</strong> Okay! All right! How was she?</p><blockquote><p>好的！好吧她怎么样？</p></blockquote><p>[Cut to Monica&#39;s bedroom]</p><blockquote><p>[转到莫妮卡的卧室]</p></blockquote><p><strong>Chandler Bing:</strong> Uh-oh.</p><blockquote><p>哦。</p></blockquote><p>[Cut to Living Room]</p><blockquote><p>[转到客厅]</p></blockquote><p><strong>Ross Geller:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Rachel Green:</strong> Was she good?</p><blockquote><p>她好吗？</p></blockquote><p>[Cut to Monica&#39;s bedroom]</p><blockquote><p>[转到莫妮卡的卧室]</p></blockquote><p><strong>Joey Tribbiani:</strong> Don’t answer that.</p><blockquote><p>别回答这个。</p></blockquote><p>[Cut to Living Room]</p><blockquote><p>[转到客厅]</p></blockquote><p><strong>Rachel Green:</strong> Come on Ross! You said you wanted to talk about it, let’s talk about it!! How was she?</p><blockquote><p>来吧，罗斯！你说你想谈谈，让我们谈谈！！她怎么样？</p></blockquote><p><strong>Ross Geller:</strong> She was...</p><blockquote><p>她是。。。</p></blockquote><p>[Cut to Monica&#39;s bedroom]</p><blockquote><p>[转到莫妮卡的卧室]</p></blockquote><p><strong>Joey Tribbiani:</strong> Awful! Horrible!</p><blockquote><p>太糟糕了！极坏的</p></blockquote><p><strong>Chandler Bing:</strong> She was not good. Not good.</p><blockquote><p>她不好。不好的。</p></blockquote><p><strong>Joey Tribbiani:</strong> She was nothing compared to you.</p><blockquote><p>和你相比，她算不了什么。</p></blockquote><p>[Cut to Living Room]</p><blockquote><p>[转到客厅]</p></blockquote><p><strong>Ross Geller:</strong> She, she was different.</p><blockquote><p>她，她不一样。</p></blockquote><p>[Cut to Monica&#39;s bedroom]</p><blockquote><p>[转到莫妮卡的卧室]</p></blockquote><p><strong>Joey Tribbiani:</strong> Ewwwww!</p><blockquote><p>哇！</p></blockquote><p><strong>Chandler Bing:</strong> Uh-oh.</p><blockquote><p>哦。</p></blockquote><p>[Cut to Living Room]</p><blockquote><p>[转到客厅]</p></blockquote><p><strong>Rachel Green:</strong> Good different?</p><blockquote><p>好的，不一样吗？</p></blockquote><p><strong>Ross Geller:</strong> Nobody likes change.</p><blockquote><p>没人喜欢变化。</p></blockquote><p><em>(Rachel picks up a newspaper and starts beating him with it.)</em></p><blockquote><p><em>（瑞秋拿起一份报纸开始用它打他。）</em></p></blockquote><p><strong>Ross Geller:</strong> What? Okay, okay, okay, okay.</p><blockquote><p>什么？好，好，好，好。</p></blockquote><p>[The next clip is from The One With The Jellyfish.]</p><blockquote><p>[下一个剪辑来自与水母有关的剪辑。]</p></blockquote><hr><p>🎬 <em>Rachel&#39;s bedroom, Rachel, entering selfish mode, is thanking Ross for wrongly taking the entire blame of the breakup; as if she had absolutely nothing to do with it.</em></p><blockquote><p>🎬 <em>瑞秋的卧室，瑞秋，进入了自私的模式，感谢罗斯错误地承担了分手的全部责任；好像她和这件事完全无关。</em></p></blockquote><p><strong>Rachel Green:</strong> ...the way you owned up to everything, it just showed me how much you’ve grown. Y&#39;know? I mean my Mom never thought this would work out. It was all, “Once a cheater, always a cheater.” Ooh, I just wish we hadn’t lost those four months, but if time was what you needed just to gain a little perspective...</p><blockquote><p>……你承认一切的方式，让我知道你成长了多少。你知道吗？我的意思是我妈妈从没想过这会成功。这都是“曾经是个骗子，永远是个骗子。”哦，我真希望我们没有失去这四个月，但如果时间是你需要的，只是为了获得一点洞察力。。。</p></blockquote><p><strong>Ross Geller:</strong> WE WERE ON A BREAK!!!!!!!</p><blockquote><p>我们在休息！！！！！！！</p></blockquote><p>[Cut back to the present.]</p><blockquote><p>[回到现在。]</p></blockquote><hr><p>🎬 <em>A mailbox, Ross is mailing the invitations. He throws a bunch into the mailbox, but pauses with Rachel&#39;s. And it starts another round of clips.</em></p><blockquote><p>🎬 <em>一个邮箱，罗斯正在邮寄邀请函。他往邮箱里扔了一堆邀请函，但在瑞秋的邮箱里停了下来。然后又开始了另一轮的剪辑。</em></p></blockquote><p>[The One With The Fake Party]</p><blockquote><p>[有假派对的那个]</p></blockquote><hr><p>🎬 <em>The hallway, Rachel is convincing Ross that Emily is good for him.</em></p><blockquote><p>🎬 <em>在走廊，瑞秋说服罗斯艾米丽对他有好处。</em></p></blockquote><p><strong>Rachel Green:</strong> You seem to really like her.</p><blockquote><p>你似乎真的很喜欢她。</p></blockquote><p><strong>Ross Geller:</strong> Yeah, I really do. Yeah, but what am I gonna do, I mean we-we both agreed that it was gonna be a two-week thing, y’know no commitment.</p><blockquote><p>是的，我真的很喜欢。是的，但我该怎么办，我是说我们都同意这是两周的事，你知道，没有承诺。</p></blockquote><p><strong>Rachel Green:</strong> Ross, that girl just spent the entire evening talking to your friends, asking to hear stories about you, looking through Monica’s photo albums, I mean you don’t do that if you’re just in it for two weeks.</p><blockquote><p>罗斯，那个女孩整晚都在和你的朋友聊天，要求听你的故事，翻看莫妮卡的相册，我是说，如果你在里面呆了两个星期，你就不会这么做。</p></blockquote><p><strong>Ross Geller:</strong> You think?</p><blockquote><p>你觉得呢？</p></blockquote><p><strong>Rachel Green:</strong> Yeah, you got like 14 hours until she has to be at the airport, and you’re sitting here in the hallway with a 28-year-old cheerleader with a fat lip.</p><blockquote><p>是啊，离她到机场还有14个小时，你和一个28岁的胖嘴唇啦啦队队长坐在走廊里。</p></blockquote><p><strong>Ross Geller:</strong> Hey, you’re right.</p><blockquote><p>嘿，你说得对。</p></blockquote><p><strong>Rachel Green:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p>[Cut back to the present, Ross is still looking at Rachel&#39;s invitation. Finally, he makes up his mind and mails it.]</p><blockquote><p>[回到现在，罗斯还在看瑞秋的邀请函。最后，他下定决心寄了出去。]</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Joey, Monica, and Phoebe are opening their invitations.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋、乔伊、莫妮卡和菲比正在打开他们的请帖。</em></p></blockquote><p><strong>Monica Geller:</strong> Ohh, this is soo amazing! I can’t believe my brother’s getting married! And in London! It’s so romantic!</p><blockquote><p>哦，这太棒了！我真不敢相信我哥哥要结婚了！在伦敦！太浪漫了！</p></blockquote><p><strong>Joey Tribbiani:</strong> (taking apart the invitation) Hey, pretty smart! Tissue paper! You’re at the wedding, you have to cry, &quot;Handkerchief?&quot; &quot;No-no, I got my invitation.&quot;</p><blockquote><p>（拆开邀请函）嘿，真聪明！纸巾！你在婚礼上，你不得不哭，“手帕？”“不，不，我收到了我的邀请。”</p></blockquote><p><strong>Phoebe Buffay:</strong> Oooh look! Isn’t this adorable, Ross let Ben address mine!</p><blockquote><p>哦，看！这不是很可爱吗，罗斯让本跟我说话！</p></blockquote><p><strong>Chandler Bing:</strong> (entering) Hello!</p><blockquote><p>（进来）你好！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Monica Geller:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Phoebe Buffay:</strong> Hey! Hey, did you get your invitation to Ross’s wedding?</p><blockquote><p>嘿！嘿，你收到罗斯婚礼的邀请了吗？</p></blockquote><p><strong>Chandler Bing:</strong> (sarcastic) Noo.</p><blockquote><p>（讽刺地）不。</p></blockquote><p><strong>Joey Tribbiani:</strong> Don’t worry man, I get to bring a guest. We’ll show him.</p><blockquote><p>别担心，伙计，我要带个客人来。我们会给他看的。</p></blockquote><p><strong>Phoebe Buffay:</strong> I’m so jealous you’re all going! I can’t believe I never knew that you can’t fly in your third trimester!</p><blockquote><p>我真嫉妒你们都要去！我真不敢相信我从来都不知道你在怀孕后期不能飞！</p></blockquote><p><strong>Chandler Bing:</strong> I didn’t know that.</p><blockquote><p>我不知道。</p></blockquote><p><strong>Monica Geller:</strong> I never knew that either.</p><blockquote><p>我也不知道。</p></blockquote><p><strong>Joey Tribbiani:</strong> I knew that! (They all look at him) I sooo didn’t know that, but you should see your faces.</p><blockquote><p>我就知道！（他们都看着他）我苏欧不知道，但你应该看看你的脸。</p></blockquote><p><strong>Rachel Green:</strong> (entering) Hey guys! What’s up?</p><blockquote><p>（进来）嘿，伙计们！怎么了？</p></blockquote><p><strong>Joey Tribbiani:</strong> Heyyy. (They all try and hide their invitations.)</p><blockquote><p>嘿。（他们都试图隐藏自己的邀请。）</p></blockquote><p><strong>Monica Geller:</strong> We’re hanging out.</p><blockquote><p>我们在一起。</p></blockquote><p><em>(Rachel starts going through her mail, and come across her invitation.)</em></p><blockquote><p><em>（瑞秋开始浏览她的邮件，偶然发现了她的邀请函。）</em></p></blockquote><p><strong>Rachel Green:</strong> What’s this? Is this Ross’s wedding invitation?</p><blockquote><p>这是什么？这是罗斯的结婚请柬吗？</p></blockquote><p><strong>Chandler Bing:</strong> See, maybe that’s the one we should’ve actually hidden.</p><blockquote><p>看，也许我们真的应该把它藏起来。</p></blockquote><p><strong>Rachel Green:</strong> Oh, no! No you guys! Come on, you don’t have to do that! I’m happy for him! I am! I really—I’m-I’m happ—I’ll work on it.</p><blockquote><p>哦，不！不，伙计们！来吧，你不必那么做！我为他高兴！我是！我真的，我很高兴，我会努力的。</p></blockquote><p><strong>Monica Geller:</strong> I’m sorry honey.</p><blockquote><p>对不起，亲爱的。</p></blockquote><p><strong>Rachel Green:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Monica Geller:</strong> Rach, you’re gonna come though aren’t you?</p><blockquote><p>瑞秋，你会来的，是吗？</p></blockquote><p><strong>Rachel Green:</strong> Oh, honey, I don’t know. I…</p><blockquote><p>哦，亲爱的，我不知道。我…</p></blockquote><p><strong>Chandler Bing:</strong> This isn’t one of those uh, y’know &quot;If she doesn’t come, we-we don’t, we don’t come?&quot; Right? Because I already bought my ticket…</p><blockquote><p>这不是那种，呃，你知道“如果她不来，我们就不来，我们就不来？”对吧？因为我已经买票了…</p></blockquote><p><strong>Monica Geller:</strong> You know what would be real weird? Is if you weren’t there. Just say you’ll think about it, okay?</p><blockquote><p>你知道什么会很奇怪吗？如果你不在的话。说你会考虑的，好吗？</p></blockquote><p><strong>Rachel Green:</strong> No, I’ll think about it. Yeah.</p><blockquote><p>不，我会考虑的。是 啊</p></blockquote><p>[And with that, we go into another set of clips, this time from Rachel’s point of view.]</p><blockquote><p>[接着，我们进入另一组剪辑，这一次是从Rachel的角度看的。]</p></blockquote><p>[The first clip is from The One Where Rachel Finds Out.]</p><blockquote><p>[第一个片段来自Rachel发现的片段。]</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, it&#39;s Rachel birthday party and Chandler is about to spill the beans.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，瑞秋生日派对，钱德勒正要说实话。</em></p></blockquote><p><strong>Rachel Green:</strong> Who&#39;s this from?</p><blockquote><p>这是谁寄来的？</p></blockquote><p><strong>Chandler Bing:</strong> Oh, that&#39;s Ross&#39;s.</p><blockquote><p>哦，那是罗斯的。</p></blockquote><p><strong>Rachel Green:</strong> Oh... (opens it and sees it is a pin) Oh my God. He remembered.</p><blockquote><p>哦。。。（打开它，看到它是一枚别针）哦，我的天啊。他记得。</p></blockquote><p><strong>Phoebe Buffay:</strong> Remembered what?</p><blockquote><p>还记得什么？</p></blockquote><p><strong>Rachel Green:</strong> It was like months ago. We were walking by this antique store, and I saw this pin in the window, and I told him that it was just like one my grandmother had when I was a little girl. Oh! I can&#39;t believe he remembered!</p><blockquote><p>就像几个月前一样。我们路过一家古董店，我在橱窗里看到了这枚别针，我告诉他这枚别针就像我小时候祖母的别针一样。哦真不敢相信他还记得！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, it&#39;s so pretty. This must have cost him a fortune.</p><blockquote><p>哦，太漂亮了。这一定花了他一大笔钱。</p></blockquote><p><strong>Monica Geller:</strong> I can&#39;t believe he did this.</p><blockquote><p>我真不敢相信他会这么做。</p></blockquote><p><strong>Chandler Bing:</strong> Come on, Ross? Remember back in college, when he fell in love with Carol and bought her that ridiculously expensive crystal duck?</p><blockquote><p>来吧，罗斯？还记得大学时，他爱上了卡萝，给她买了一只贵得离谱的水晶鸭吗？</p></blockquote><p><em>(Everyone looks at him. He realizes he just spilled the beans about Ross&#39;s crush on Rachel.)</em></p><blockquote><p><em>（每个人都看着他。他意识到他刚刚泄露了罗斯迷恋瑞秋的秘密。）</em></p></blockquote><p><strong>Rachel Green:</strong> What did you just say?</p><blockquote><p>你刚才说什么？</p></blockquote><p><strong>Chandler Bing:</strong> (stuttering incoherently) F-hah.... flennin....</p><blockquote><p>（结结巴巴地说）哈哈。。。。弗莱宁。。。。</p></blockquote><p><strong>Rachel Green:</strong> Oh.... my God.</p><blockquote><p>哦。。。。天哪。</p></blockquote><p>[The next clip is from The One With Ross&#39;s New Girlfriend.]</p><blockquote><p>[下一个剪辑来自罗斯的新女友。]</p></blockquote><hr><p>🎬 <em>The airport, Ross is about to walk off of the plane with Julie.</em></p><blockquote><p>🎬 <em>机场，罗斯正要和朱莉一起走下飞机。</em></p></blockquote><p><strong>Rachel Green:</strong> (seeing Ross come off the plane with another woman.) Oh my God.</p><blockquote><p>（看到罗斯和另一个女人下飞机。）哦，天哪。</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Ross is introducing Julie to the gang.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，罗斯正在向帮派介绍朱莉。</em></p></blockquote><p><strong>Julie:</strong> Well, Ross and I were in grad school together.</p><blockquote><p>嗯，罗斯和我一起读研究生。</p></blockquote><p><strong>Ross Geller:</strong> But we haven&#39;t seen each other since then. Well I land in China, guess who&#39;s in charge of the dig.</p><blockquote><p>但从那以后我们就没见过面了。我在中国登陆，猜猜谁负责挖掘。</p></blockquote><p><strong>Rachel Green:</strong> Julie! Julie, isn&#39;t that great? I mean, isn&#39;t that just kick- you-in-the-crotch, spit-on-your-neck fantastic?</p><blockquote><p>朱莉！朱莉，那不是很棒吗？我的意思是，这不就是踢你的胯部，吐唾沫在你脖子上吗？</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Ross is trying to hang up on Julie.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，罗斯正试图挂断朱莉的电话。</em></p></blockquote><p><strong>Ross Geller:</strong> Oh, that is so sweet.(listens) No, no, ok, you hang up. Ok, ok, one, two, three.(He doesn&#39;t hang up and motions for Rachel to be quiet.) Well you didn&#39;t hang up either.</p><blockquote><p>哦，太好了。（听着）不，不，好吧，你挂断。好，好，一，二，三。（他没有挂断电话，示意瑞秋安静。）你也没有挂。</p></blockquote><p><strong>Rachel Green:</strong> She didn&#39;t hang up either...</p><blockquote><p>她也没有挂断。。。</p></blockquote><p><strong>Ross Geller:</strong> Ok, no, no, you hang up. You, you, y—(Rachel grabs the phone and hangs it up for him.)</p><blockquote><p>好的，不，不，你挂断。你，你，你-（瑞秋抓起电话为他挂上。）</p></blockquote><p>[The next clip is from The One Where Ross Finds Out.]</p><blockquote><p>[下一个片段来自罗斯发现的片段。]</p></blockquote><p>[Scene, A Restaurant, Rachel is on her date, drunk, and is leaving that answering machine message.]</p><blockquote><p>[场景，一家餐馆，瑞秋正在约会，喝醉了，正在留言机上留言。]</p></blockquote><p><strong>Rachel Green:</strong> (on phone) Ross, hi, it&#39;s Rachel. I&#39;m just calling to say that um, everything&#39;s fine and I&#39;m really happy for you and your cat...(cut)...I am over you. I am over you and that, my friend, is what they call closure. (She hangs up and tosses phone in the ice bucket.)</p><blockquote><p>（打电话）罗斯，你好，我是瑞秋。我打电话只是想说，嗯，一切都很好，我真的为你和你的猫感到高兴…（切）…我不理你了。我不在乎你了，我的朋友，这就是他们所说的结束。（她挂断电话，把电话扔进了冰桶。）</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p>[Scene, Monica and Rachel&#39;s, the next morning, Ross is checking his messages.]</p><blockquote><p>[场景，莫妮卡和瑞秋家，第二天早上，罗斯正在查看他的留言。]</p></blockquote><p><strong>Ross Geller:</strong> Rach, I got a message from you.</p><blockquote><p>瑞秋，我收到你的口信了。</p></blockquote><p><em>(Rachel comes out of her room, suddenly she remembers leaving the message.)</em></p><blockquote><p><em>（瑞秋走出房间，突然想起留下了留言。）</em></p></blockquote><p><strong>Rachel Green:</strong> Oh my God. Oh my God Ross, no, hang up the phone, give me the phone Ross, give me the phone, give me the phone, give me the. . . (She jumps the couch and lands on Ross&#39;s back, finally getting the phone from him. Ross has a confused expression on his face.)</p><blockquote><p>我的天啊。哦，天哪，罗斯，不，挂断电话，给我电话罗斯，给我电话，给我电话，给我电话。（她跳到沙发上，坐在罗斯的背上，终于从他那里拿到了电话。罗斯脸上有一种困惑的表情。）</p></blockquote><p><strong>Ross Geller:</strong> You&#39;re over me?</p><blockquote><p>你忘了我了？</p></blockquote><p><strong>Rachel Green:</strong> Ohhhhhhhh God. (climbs off his back)</p><blockquote><p>天啊。（从他的背上爬下来）</p></blockquote><p><strong>Ross Geller:</strong> Wha... you&#39;re uh, you&#39;re, you&#39;re over me?</p><blockquote><p>什么。。。你，呃，你，你已经超过我了？</p></blockquote><p><strong>Rachel Green:</strong> Ohh, ohh.</p><blockquote><p>哦，哦。</p></blockquote><p><strong>Ross Geller:</strong> When, when were you... under me?</p><blockquote><p>什么时候，你什么时候。。。在我下面？</p></blockquote><p><strong>Rachel Green:</strong> Well, basically, lately, I&#39;ve uh, I&#39;ve uh, sort of had feelings for you.</p><blockquote><p>嗯，基本上，最近，我对你有点感觉。</p></blockquote><p>[cut to later in the same scene]</p><blockquote><p>[切换到同一场景中的稍后部分]</p></blockquote><p><strong>Ross Geller:</strong> OK, I need to lie down.</p><blockquote><p>好的，我需要躺下。</p></blockquote><p>[The next clip is from The One With The List.]</p><blockquote><p>[下一个剪辑来自列表中的剪辑。]</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, Ross has just broken up with Julie and is about to get with Rachel.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊家，罗斯刚刚和朱莉分手，准备和瑞秋约会。</em></p></blockquote><p><strong>Joey Tribbiani:</strong> He broke up with Julie. Well, go hug her, for god&#39;s sakes.</p><blockquote><p>他和朱莉分手了。看在上帝的份上，去拥抱她吧。</p></blockquote><p><strong>Rachel Green:</strong> Really?</p><blockquote><p>真的吗？</p></blockquote><p><strong>Ross Geller:</strong> Really. It&#39;s always been you, Rach.</p><blockquote><p>真的。一直都是你，瑞秋。</p></blockquote><p><strong>Rachel Green:</strong> Oh, god.</p><blockquote><p>哦，天啊。</p></blockquote><p><em>(Ross and Rachel hug.)</em></p><blockquote><p><em>（罗斯和瑞秋拥抱。）</em></p></blockquote><p>Chandler and **Joey Tribbiani: **Ohhh.</p><blockquote><p>钱德勒和<strong>乔伊·崔比安尼：</strong>哦。</p></blockquote><p>[The next clip is from The One Where Ross and Rachel.... You Know.]</p><blockquote><p>[下一个剪辑来自罗斯和瑞秋……你知道的。]</p></blockquote><hr><p>🎬 <em>The Auditorium, Ross and Rachel are about to... you know.</em></p><blockquote><p>🎬 <em>礼堂，罗斯和瑞秋即将……你知道的。</em></p></blockquote><p><strong>Ross Geller:</strong> I&#39;ve no idea, could be. Listen, I&#39;m sorry I had to work tonight.</p><blockquote><p>我不知道，可能是。听着，很抱歉我今晚要工作。</p></blockquote><p><strong>Rachel Green:</strong> Oh it&#39;s OK. You were worth the wait, and I don&#39;t just mean tonight.</p><blockquote><p>哦，没关系。你值得等待，我不是说今晚。</p></blockquote><p><em>(They kiss and start undressing. As Rachel tries to pull off Ross&#39;s tie she catches it in his mouth. Then they roll across the fur rug.)</em></p><blockquote><p><em>（他们接吻并开始脱衣服。瑞秋试图脱下罗斯的领带时，她抓住了罗斯的嘴。然后他们在毛皮地毯上打滚。）</em></p></blockquote><p><strong>Rachel Green:</strong> Ah, oh God. Oh, honey, oh that&#39;s OK.</p><blockquote><p>啊，天啊。亲爱的，没关系。</p></blockquote><p><strong>Ross Geller:</strong> What. Oh no, you just rolled over the juice box.</p><blockquote><p>什么。哦，不，你刚才把果汁盒翻了。</p></blockquote><p>[The next clip is from The One The Morning After.]</p><blockquote><p>[下一个剪辑来自第二天早上的剪辑。]</p></blockquote><hr><p>🎬 <em>Central Perk, Ross is trying to prevent Gunther from spilling the beans.</em></p><blockquote><p>🎬 <em>中央公园，罗斯试图阻止冈瑟泄露秘密。</em></p></blockquote><p><strong>Ross Geller:</strong> Gunther! Gunther. Gunther, please tell me you didn’t say anything to Rachel about me and the girl from the Xerox place.</p><blockquote><p>冈瑟！冈瑟。冈瑟，请告诉我你没有对瑞秋说我和施乐公司那个女孩的事。</p></blockquote><p><strong>Gunther:</strong> I’m sorry. Was I not supposed to?</p><blockquote><p>对不起。难道我不该这么做吗？</p></blockquote><p><em>(Ross turns around and sees Rachel sitting by the window. She is just glaring at him.)</em></p><blockquote><p><em>（罗斯转过身，看到瑞秋坐在窗边。她只是瞪着他。）</em></p></blockquote><p>[The next clip is from The One At The Beach.]</p><blockquote><p>[下一个剪辑来自海滩上的一个剪辑。]</p></blockquote><hr><p>🎬 <em>The beachhouse, Ross and Rachel are argueing about the breakup.</em></p><blockquote><p>🎬 <em>海滩小屋，罗斯和瑞秋正在为分手争吵。</em></p></blockquote><p><strong>Ross Geller:</strong> Y&#39;know, hey! You’re the one who ended it, remember?</p><blockquote><p>你知道，嘿！是你结束的，记得吗？</p></blockquote><p><strong>Rachel Green:</strong> Yeah, because I was mad at you, not because I stopped loving you!</p><blockquote><p>是啊，因为我生你的气，不是因为我不再爱你了！</p></blockquote><p><strong>Ross Geller:</strong> You still love me?</p><blockquote><p>你还爱我吗？</p></blockquote><p><strong>Rachel Green:</strong> Noo.</p><blockquote><p>不。</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><strong>Ross Geller:</strong> What does this mean? What do you, I mean do you wanna, get back together?</p><blockquote><p>这是什么意思？你是什么意思，你想重归于好吗？</p></blockquote><p><strong>Rachel Green:</strong> Noo! Maybe! I, I don’t know.</p><blockquote><p>不！大概一、 我不知道。</p></blockquote><p><strong>Ross Geller:</strong> What?!</p><blockquote><p>什么？！</p></blockquote><p><strong>Rachel Green:</strong> I just, I feel, I-I just...</p><blockquote><p>我只是，我觉得，我只是。。。</p></blockquote><p><em>(Ross leans in and kisses her. They both look at each other for a moment, and then embrace in a more passionate kiss.)</em></p><blockquote><p><em>（罗斯俯身吻了她。他们彼此看了一会儿，然后拥抱在一起，吻得更热烈。）</em></p></blockquote><p>[The next clip is from The One With The Jellyfish.]</p><blockquote><p>[下一个剪辑来自与水母有关的剪辑。]</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Rachel and Ross are finally breaking up for good, or is it?</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的，瑞秋和罗斯终于分手了，是吗？</em></p></blockquote><p><strong>Rachel Green:</strong> Y&#39;know I can’t believe I even thought about getting back together again! We are so over!!</p><blockquote><p>你知道吗，我简直不敢相信我甚至还想过要重归于好！我们结束了！！</p></blockquote><p><strong>Ross Geller:</strong> (starts to cry) FINE BY ME!! (he opens the door and traps Chandler behind it)</p><blockquote><p>（开始哭）我很好！！（他打开门，把钱德勒困在门后）</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><strong>Rachel Green:</strong> And hey! Just so you know, it’s not that common! It doesn’t happen to every guy! And it is a big deal!!</p><blockquote><p>嘿！你要知道，这并不常见！不是每个人都会这样！这是一件大事！！</p></blockquote><p><strong>Chandler Bing:</strong> I KNEW IT!!!!</p><blockquote><p>我就知道！！！！</p></blockquote><p>[cut back to the present.]</p><blockquote><p>[回到现在。]</p></blockquote><hr><p>🎬 <em>Central Perk, Rachel is deciding on whether or not to go to the wedding.</em></p><blockquote><p>🎬 <em>中央公园，瑞秋正在决定是否去参加婚礼。</em></p></blockquote><p>[cut to another clip, this one is from The One With The Prom Video]</p><blockquote><p>[剪切到另一个剪辑，这是从一个与舞会视频]</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, the gang is watching the Prom Video and Rachel is about to make her entrance on the video. The italics are portions of the prom video.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，这帮人正在看舞会视频，瑞秋正要进入视频。斜体是舞会视频的一部分。</em></p></blockquote><p>Mrs. Geller: Rachel&#39;s coming up the path. Doesn&#39;t she look pretty. Jack... (Rachel enters with a huge nose)</p><blockquote><p>瑞秋正沿着小路走来。她看起来不漂亮吗。杰克。。。（瑞秋大鼻子走了进来）</p></blockquote><p><strong>Rachel Green:</strong> Oh my God.</p><blockquote><p>我的天啊。</p></blockquote><p><strong>Monica Geller:</strong> You know what this is, this is us getting ready for the prom.</p><blockquote><p>你知道这是什么，这是我们为舞会做准备。</p></blockquote><p><strong>Rachel Green:</strong> Oh.</p><blockquote><p>哦。</p></blockquote><p><strong>Ross Geller:</strong> You know what, you guys, we don&#39;t have to watch this.</p><blockquote><p>你们知道吗，伙计们，我们不必看这个。</p></blockquote><p><strong>All:</strong> Oh yeah we do. C&#39;mon.</p><blockquote><p>哦，是的，我们有。拜托。</p></blockquote><p>Mrs. Geller: Get a shot of Monica. Where&#39;s Monica.</p><blockquote><p>给莫妮卡拍张照。莫妮卡在哪里。</p></blockquote><p>Mr. Geller: Wait, how do you zoom out? (zooms out and we see an extremely overweight Monica eating a big sandwich) There she is.</p><blockquote><p>等等，你怎么缩小？（放大，我们看到一个超重的莫妮卡正在吃一个大三明治）她在那里。</p></blockquote><p><strong>Monica Geller:</strong> Shut up, the camera adds ten pounds.</p><blockquote><p>闭嘴，这相机增加了十磅。</p></blockquote><p><strong>Chandler Bing:</strong> Ahh, so how many cameras are actually on you?</p><blockquote><p>啊，那么你身上到底有多少个摄像头？</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><strong>Monica Geller:</strong> Oh, dad, turn it off.</p><blockquote><p>哦，爸爸，把它关掉。</p></blockquote><p>Mr. Geller: It is off. Right Ross? (pans over to see Ross with an afro and moustache)</p><blockquote><p>关了。对吧，罗斯？（俯视着留着非洲裔和小胡子的罗斯）</p></blockquote><p><strong>Joey Tribbiani:</strong> Lookin&#39; good Mr. Cotter.</p><blockquote><p>看起来不错，科特先生。</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><strong>Rachel Green:</strong> I can&#39;t go to my own prom without a date, I can&#39;t, it&#39;s too late.</p><blockquote><p>我不能不约会就去参加我自己的舞会，我不能，太晚了。</p></blockquote><p><strong>Monica Geller:</strong> If you&#39;re not going then I don&#39;t want to go either.</p><blockquote><p>如果你不去，我也不想去。</p></blockquote><p>Mrs. Geller: (to Ross on the stairs) I have a wonderful idea. You should take Rachel to the prom.</p><blockquote><p>（对楼梯上的罗斯）我有个好主意。你应该带瑞秋去舞会。</p></blockquote><p>[cut to later]</p><blockquote><p>[切换到稍后]</p></blockquote><p><strong>Ross Geller:</strong> Y&#39;know what? I think we&#39;ve seen enough, let&#39;s turn it off.</p><blockquote><p>你知道吗？我想我们已经看够了，把它关掉吧。</p></blockquote><p><strong>All:</strong> No, no, no.</p><blockquote><p>不，不，不。</p></blockquote><p><strong>Ross Geller:</strong> OK, fine, well I&#39;m not gonna watch, alright.</p><blockquote><p>好吧，好吧，我不看了，好吧。</p></blockquote><p>Mr. Geller: C&#39;mon kid, let&#39;s go.</p><blockquote><p>来吧，孩子，我们走。</p></blockquote><p>Mrs. Geller: Ahh, are you hadsome.</p><blockquote><p>啊，你有吗。</p></blockquote><p>Mr. Geller: Let&#39;s show &#39;em.</p><blockquote><p>让我们给他们看看。</p></blockquote><p><strong>Ross Geller:</strong> (walks down the stairs and grabs the flowers out of the vase on the endtable) Okay dad.</p><blockquote><p>（走下楼梯，从桌尾的花瓶里拿出花）好的，爸爸。</p></blockquote><p>Mr. Geller: (going downstairs) Rachel, ready or not, here comes your knight in shining—Oh no. (Chip has shown up and the four are leaving.)</p><blockquote><p>（下楼）瑞秋，准备好了没有，你的骑士来了哦不。（奇普已经出现了，四个人要走了。）</p></blockquote><p>Rachel, Monica, Roy, and Chip: Bye.</p><blockquote><p>瑞秋、莫妮卡、罗伊和奇普：再见。</p></blockquote><p>Mrs. Geller: Oh, dear. Jack, how do I turn this off?</p><blockquote><p>哦，亲爱的。杰克，我怎么关掉这个？</p></blockquote><p><strong>Monica Geller:</strong> (to Ross) I can&#39;t believe you did that.</p><blockquote><p>（对罗斯）我真不敢相信你这么做。</p></blockquote><p><strong>Ross Geller:</strong> Yeah, well.</p><blockquote><p>是的，嗯。</p></blockquote><p>[Rachel, seeing what he did for her, gets up, walks across the room, and kisses Ross]</p><blockquote><p>[瑞秋，看到他为她做了什么，站起来，穿过房间，吻了罗斯]</p></blockquote><p><strong>Phoebe Buffay:</strong> See, he&#39;s her lobster.</p><blockquote><p>看，他是她的龙虾。</p></blockquote><p>[Cut back to the present, Rachel has made her decision.]</p><blockquote><p>[回到现在，瑞秋已经做出了决定。]</p></blockquote><p><strong>Monica Geller:</strong> (seeing the decision) Nooooo. You’re really not going?</p><blockquote><p>（看到决定）不。你真的不去吗？</p></blockquote><p><strong>Rachel Green:</strong> Yeah. It’s just gonna be too hard. Y’know? I mean, it’s Ross. How can I watch him get married? Y’know it’s just, it’s for the best, y’know it is, it’s… Y’know, plus, somebody’s got to stay here with Phoebe! Y’know she’s gonna be pretty big by then, and she needs someone to help her tie her shoes; drive her to the hospital in case she goes into labour.</p><blockquote><p>是的。这太难了。你知道吗？我是说，是罗斯。我怎么能看着他结婚？你知道这只是，这是最好的，你知道，这是…你知道，另外，有人必须和菲比呆在一起！你知道她那时会很高大，她需要有人帮她系鞋带；开车送她去医院，以防她分娩。</p></blockquote><p><strong>Monica Geller:</strong> You don’t have a car. And your license expired.</p><blockquote><p>你没有车。你的驾照过期了。</p></blockquote><p><strong>Rachel Green:</strong> I know. (Starts to cry) Yeah, see, there’s so much to do and I have so little time to do it in.</p><blockquote><p>我知道。（开始哭）是的，看，有这么多事情要做，而我几乎没有时间去做。</p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>Central Perk, Chandler, Joey, and Phoebe are reading a book about things to do whilst in London.</em></p><blockquote><p>🎬 <em>中央公园、钱德勒、乔伊和菲比正在读一本关于在伦敦期间要做的事情的书。</em></p></blockquote><p><strong>Chandler Bing:</strong> All right, check it out. Check this out. It says here that there’s a place you can go to rent videos of all the museums! (Reading from the book.) &quot;It’s almost as good as being there.&quot;</p><blockquote><p>好吧，看看。看看这个。这里说有一个地方你可以去租所有博物馆的录像带！（从书中读到。）“这几乎和在那里一样好。”</p></blockquote><p><strong>Joey Tribbiani:</strong> It’s better! You can’t go to a museum in your underwear!</p><blockquote><p>好多了！你不能穿着内衣去博物馆！</p></blockquote><p><strong>Chandler Bing:</strong> Well, You could, but... probably just the one time.</p><blockquote><p>嗯，你可以，但是。。。也许只有一次。</p></blockquote><p><strong>Joey Tribbiani:</strong> I bet we could get videos of all the sites, get a VCR in our hotel room... we&#39;d never even have to go outside!</p><blockquote><p>我打赌我们可以拍到所有网站的视频，在我们的酒店房间里放一台录像机。。。我们甚至不需要出去！</p></blockquote><p><strong>Chandler Bing:</strong> If we do that, we gotta get Die Hard.</p><blockquote><p>如果我们那样做，我们就得硬着头皮。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh-ho! I bet the British version is gooooood!</p><blockquote><p>哦，好！我敢打赌英国版本是好的！</p></blockquote>`,737)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};